                payment_method_id: None,
                mandate_metadata: None,
                connector_mandate_request_reference_id: None,
            });

        let connector_transaction_id = item
            .response
            .payment_id
            .unwrap_or_else(|| item.response.id.clone());

        match item.response.status {
            MolliePaymentStatus::Failed | MolliePaymentStatus::Expired => {
                let (code, message, reason) = match (
                    &item.response.details,
                    &item.response.status_reason,
                ) {
                    (Some(details), _) => {
                        let code = details
                            .failure_reason
                            .clone()
                            .unwrap_or_else(|| consts::NO_ERROR_CODE.to_string());
                        let message = details
                            .failure_message
                            .clone()
                            .unwrap_or_else(|| consts::NO_ERROR_MESSAGE.to_string());
                        let reason = details.failure_reason.clone();
                        (code, message, reason)
                    }
                    (_, Some(status_reason)) => {
                        let code = status_reason.code.clone();
                        let message = status_reason.message.clone();
                        (code, message, Some(message.clone()))
                    }
